import { z } from 'zod';

// `code` is auto-generated by the CRUD factory (CUS-0001, CUS-0002, ...)
// matching the frontend's mock data convention, unless the client supplies
// one explicitly.
export const createCustomerSchema = z.object({
  code: z.string().trim().min(1).optional(),
  name: z.string().trim().min(1, 'Customer name is required'),
  // Exactly 10 digits, numeric only — no spaces, dashes, +91, letters, etc.
  // The frontend also blocks non-digit keystrokes and caps input at 10
  // characters (see FormTextField's `numeric`/`maxLength` props), so this is
  // the server-side backstop for any client that doesn't.
  mobile: z.string().trim().regex(/^\d{10}$/, 'Enter a valid 10-digit mobile number'),
  email: z.string().trim().email('Enter a valid email').optional().or(z.literal('')).nullable(),
  gstin: z.string().trim().optional().nullable(),
  customerType: z.string().trim().min(1, 'Select a customer type'),
  group: z.string().trim().optional().nullable(),
  priceCategory: z.string().trim().optional().nullable(),
  creditLimit: z.coerce.number().nonnegative('Credit limit cannot be negative').default(0),
  openingBalance: z.coerce.number().default(0),
  openingBalanceType: z.enum(['Cr', 'Dr']).default('Cr'),
  address: z.string().trim().optional().nullable(),
  salesRepresentative: z.string().trim().optional().nullable(),
  territory: z.string().trim().optional().nullable(),
  allowCreditSale: z.boolean().default(true),
  priceInclusive: z.boolean().default(false),
  smsNotification: z.boolean().default(true),
  notes: z.string().trim().optional().nullable(),
  status: z.enum(['ACTIVE', 'INACTIVE']).default('ACTIVE'),
});

export const updateCustomerSchema = createCustomerSchema.partial();
